{
  "name": "opencode-temporal",
  "version": "0.1.1",
  "description": "Temporal Cloud tools for OpenCode — schedules and workflows through the temporal CLI, authenticated with `temporal cloud login` OAuth instead of static API keys",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "temporal",
    "temporalio",
    "temporal-cloud",
    "workflow",
    "schedules",
    "durable-execution"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MehdiZare/opencode-temporal.git"
  },
  "homepage": "https://github.com/MehdiZare/opencode-temporal#readme",
  "bugs": {
    "url": "https://github.com/MehdiZare/opencode-temporal/issues"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "devDependencies": {
    "@types/bun": "^1.4.4",
    "typescript": "^7.0.2"
  }
}
